class Solution:
    def kthSmallest(self, matrix: List[List[int]], k: int) -> int:
        n = len(matrix)
        lo, hi = matrix[0][0], matrix[n-1][n-1]
        while lo < hi:
            mid = (lo + hi) // 2
            count = 0
            for i in range(n):
                j = n - 1
                while j >= 0 and matrix[i][j] > mid:
                    j -= 1
                count += j + 1
            if count >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

reference_solution.javascript:
function kthSmallest(matrix, k) {
    const n = matrix.length;
    let lo = matrix[0][0], hi = matrix[n-1][n-1];
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        let count = 0;
        for (let i = 0; i < n; i++) {
            let j = n - 1;
            while (j >= 0 && matrix[i][j] > mid) j--;
            count += j + 1;
        }
        if (count >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}
